package gis
import("fmt";"net/netip";"sort";"strings";"sync")
type IPAM struct{mu sync.RWMutex;assets map[string]IPAsset}
func NewIPAM()*IPAM{return &IPAM{assets:make(map[string]IPAsset)}}
func(i *IPAM)Upsert(asset IPAsset)error{if i==nil{return fmt.Errorf("ipam is required")};asset.ID=strings.TrimSpace(asset.ID);asset.IP=strings.TrimSpace(asset.IP);asset.CIDR=strings.TrimSpace(asset.CIDR);if asset.ID==""||asset.IP==""{return fmt.Errorf("id and ip are required")};if len(asset.ID)>256||len(asset.IP)>64||len(asset.CIDR)>64{return fmt.Errorf("IPAM field is too large")};ip,err:=netip.ParseAddr(asset.IP);if err!=nil{return fmt.Errorf("invalid ip: %w",err)};asset.IP=ip.String();if asset.CIDR!=""{prefix,err:=netip.ParsePrefix(asset.CIDR);if err!=nil{return fmt.Errorf("invalid cidr: %w",err)};asset.CIDR=prefix.String()};i.mu.Lock();defer i.mu.Unlock();if i.assets==nil{i.assets=make(map[string]IPAsset)};i.assets[asset.ID]=asset;return nil}
func(i *IPAM)List()[]IPAsset{if i==nil{return []IPAsset{}};i.mu.RLock();out:=make([]IPAsset,0,len(i.assets));for _,a:=range i.assets{out=append(out,a)};i.mu.RUnlock();sort.Slice(out,func(a,b int)bool{if out[a].IP!=out[b].IP{return out[a].IP<out[b].IP};return out[a].ID<out[b].ID});return out}
